      "answer": "<div style='background-color:#f0f8ff; padding:15px; border-left:5px solid #16a085; border-radius:8px;'><p><strong>ઉકેલ/જવાબ:</strong> સાચો વિકલ્પ A છે. સૂત્ર: n(A ∪ B) = n(A) + n(B) - n(A ∩ B). તેથી, 40 = 20 + 30 - n(A ∩ B) ⇒ n(A ∩ B) = 50 - 40 = 10.</p><hr><p style='color:#d32f2f; font-weight:bold;'>💡 નિતેશ સરની શોર્ટકટ ટ્રીક: NJ Classes - અલગ-અલગ સંખ્યાઓનો સરવાળો કરી 'ટોટલ' (યુનિયન) બાદ કરો, એટલે કોમન (છેદ) મળી જાય.</p></div>"
