      "questionNumber": "પ્રશ્ન 67",
      "question": "જો $2x + 1 \ge 3$ અને $3x - 5 \le 1$ હોય, તો $x$ નો ઉકેલ ગણ:\n(A) $[1, 2]$\n(B) $(1, 2)$\n(C) $[1, \infty)$\n(D) $(-\infty, 2]$ ",
